<?php require __DIR__.'/includes/bootstrap.php';$items=[];$total=0;if(cart_items()){$ids=array_keys(cart_items());$in=implode(',',array_fill(0,count($ids),'?'));$s=db()->prepare("SELECT id,name,price,image_url,stock FROM products WHERE id IN ($in) AND is_active=1");$s->execute($ids);foreach($s->fetchAll() as $p){$p['qty']=min((int)$p['stock'],(int)cart_items()[$p['id']]);$p['line']=$p['qty']*(float)$p['price'];$total+=$p['line'];$items[]=$p;}}?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>سلة المشتريات</title><link rel="stylesheet" href="assets/css/store.css"></head><body><?php include __DIR__.'/includes/nav.php';?><main class="inner"><h1>سلة المشتريات</h1><?php if(!$items):?><p>السلة فارغة حالياً. <a href="index.php">تابع التسوق</a></p><?php else:?><form method="post" action="cart-action.php"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="update"><div class="cart-list"><?php foreach($items as $p):?><div class="cart-row"><img src="<?=h($p['image_url'])?>" alt=""><div><b><?=h($p['name'])?></b><p><?=money($p['price'])?></p><input type="number" min="0" max="<?=$p['stock']?>" name="qty[<?=$p['id']?>]" value="<?=$p['qty']?>"></div><strong><?=money($p['line'])?></strong><form method="post" action="cart-action.php"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="<?=$p['id']?>"><button type="submit">حذف</button></form></div><?php endforeach?></div><button class="gold">تحديث السلة</button></form><h2>الإجمالي: <?=money($total)?></h2><a class="gold" href="checkout.php">إتمام الطلب</a><?php endif?></main><?php include __DIR__.'/includes/footer.php';?></body></html>